pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // However, we use a non-linear weight to discourage leaving space < 10 (dead zones).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead Coupling: 
    // If the next item can perfectly or near-perfectly fill the current post_residual, reward this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

        // If the next item fits perfectly in the resulting hole, prioritize this bin heavily.
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        }
    }

    // 3. Harmonic Class Logic:
    // Prefer bins that align with common fractions of capacity (e.g., 1/2, 1/3, 1/4).
    let residual_fraction = (post_residual as f64) / (bin_capacity as f64);
    if (residual_fraction - 0.5).abs() < 0.05 || (residual_fraction - 0.33).abs() < 0.05 {
        score -= 5.0;
    }

    // 4. Scarcity/Progression logic:
    // As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many fitting options.
        score += (fitting_bins_count as f64 * 20.0) * (1.0 + progress);
    }

    // 5. Mean-Residual Balancing:
    // Avoid bins that deviate significantly from the average state of existing bins to keep packing uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // Already established by the base score.

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, heavily prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0;
        // Reward tighter fits that leave exactly enough for the next item
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Fragmentation Avoidance: If post_residual is small but > 0, it's often "dead space".
    // We penalize very small residuals that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Mean Residual Balancing: Avoid bins that deviate significantly from the average occupancy.
    // This helps keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless the
    // options in existing bins are very poor (high post_residual).
    if bin_residual == bin_capacity {
        // High cost to open a new bin; only do it if the average residual of 
        // existing bins is already very low (meaning we are tightly packed).
        score += 65.0 - (mean_residual * 0.5);
    }

    // 6. Last Chance Logic: If this is the only bin that can fit the item, 
    // it is highly desirable regardless of the residual.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Adaptive Best-Fit with lookahead-aware capacity preservation.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base penalty: The tighter the fit, the better (minimize post_residual).
    let mut score = post_residual as f64;

    // 2. Dead-space penalty: Avoid creating "slivers" (very small residuals that are hard to fill).
    // Specifically penalize residuals in the (0, 10) range, as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration:
    // If we have a next item, try to ensure the post_residual can accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize if the current placement prevents the next item from fitting here.
            score += 25.0;
        } else {
            // Reward if the current placement leaves space for the next item.
            score -= 15.0;
        }
    }

    // 4. Global state pressure:
    // If fitting_bins_count is 1, we are at a "critical" state for this item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0; // Strongly prefer filling the last available fitting bin.
    }

    // 5. New bin logic:
    // Only open a new bin if the current open bins are "bad" fits (high post_residual).
    if is_new_bin {
        if open_bins_count == 0 {
            score = 0.0; // Must open a new bin if no bins exist.
        } else {
            // Heavily penalize opening a new bin unless existing bins are very inefficient.
            // We compare against the mean_residual of existing bins.
            score = 40.0 + (mean_residual * 0.5);

            // Late-game bias: be more aggressive opening bins as we approach the end.
            score -= (progress * 20.0);
        }
    }

    score
}
